// Extract batch search parameters
const queries = $input.item.json.queries || []; // Array of query strings
const mode = $input.item.json.mode || 'union'; // union or intersection
const limit = $input.item.json.limit || 5;
const minScore = $input.item.json.min_score || 0.7;
const conversationId = $input.item.json.conversation_id;

if (!Array.isArray(queries) || queries.length === 0) {
  throw new Error('queries array is required and must not be empty');
}

return {
  queries,
  mode,
  limit,
  minScore,
  conversationId,
  timestamp: new Date().toISOString()
};

// Format batch search results for MS Teams
const results = $input.item.json.results || [];
const mode = $input.item.json.mode || 'union';
const metadata = $input.item.json.metadata || {};

let message = `**Batch Search Results (${mode} mode)**\n\n`;
message += `Queries: ${metadata.queries_count || 0} | Total Results: ${metadata.total_results || 0}\n\n`;

if (results.length === 0) {
  message += '⚠️ No matching documents found.\n';
} else {
  results.forEach((result, index) => {
    message += `**${index + 1}. ${result.file_name || 'Unknown'}**\n`;
    message += `📄 Score: ${(result.score || 0).toFixed(3)}\n`;

    if (result.matched_queries && result.matched_queries.length > 0) {
      message += `✅ Matched queries: ${result.matched_queries.length}\n`;
    }

    if (result.text) {
      const preview = result.text.substring(0, 150);
      message += `\n${preview}${result.text.length > 150 ? '...' : ''}\n`;
    }

    message += '\n---\n\n';
  });
}

return {
  message,
  conversation_id: $input.item.json.conversation_id
};

// Return formatted response
return {
  json: {
    success: true,
    message: $json.message,
    conversation_id: $json.conversation_id
  }
};
